// Ironspire offline support. Generated by tools/build.js, do not edit by hand.
// The game page: try the network first so a new build shows up right away, fall
// back to the saved copy when offline. Fonts and icons: saved copy first.
const CACHE = 'ironspire-3a37d4eea0';
const SHELL = ['./', 'index.html', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png', 'icon-maskable-512.png', 'apple-touch-icon.png'];
const FONT_CSS = "https://fonts.googleapis.com/css2?family=Russo+One&family=Chakra+Petch:wght@400;500;600;700&display=swap";
// Save the fonts at install time, so the first offline launch already has them.
// Best effort: with no fonts the game falls back to system type and still runs.
async function saveFonts(cache) {
  if (!FONT_CSS) return;
  try {
    const css = await (await fetch(FONT_CSS)).text();
    await cache.put(FONT_CSS, new Response(css, { headers: { 'Content-Type': 'text/css; charset=utf-8' } }));
    const parts = css.split('@font-face'), urls = [];
    for (let i = 1; i < parts.length; i++) {
      const subset = (parts[i - 1].match(/\/\*\s*([\w-]+)\s*\*\/\s*$/) || [])[1];
      const url = (parts[i].match(/url\((https:[^)]+)\)/) || [])[1];
      if (url && (!subset || subset === 'latin')) urls.push(url);
    }
    await Promise.all(urls.map((u) => fetch(u).then((r) => (r.ok ? cache.put(u, r) : null)).catch(() => null)));
  } catch (err) {}
}
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL).then(() => saveFonts(c))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const sameOrigin = url.origin === self.location.origin;
  const isFont = url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com';
  if (!sameOrigin && !isFont) return;
  const isPage = sameOrigin && (req.mode === 'navigate' || url.pathname.endsWith('/') || url.pathname.endsWith('index.html'));
  if (isPage) {
    e.respondWith(
      fetch(req).then((res) => { const copy = res.clone(); caches.open(CACHE).then((c) => c.put('index.html', copy)); return res; })
        .catch(() => caches.match('index.html').then((hit) => hit || caches.match('./')))
    );
    return;
  }
  e.respondWith(
    caches.match(req, { ignoreVary: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res && (res.ok || res.type === 'opaque')) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    }))
  );
});
